const assert = require('assert');
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const todoJs = path.join(__dirname, 'todo.js');
const todoJson = path.join(__dirname, 'todo.json');

// Read todo.js source — verify exists & non‑empty
const todoJsContent = fs.readFileSync(todoJs, 'utf8');
assert.ok(todoJsContent.length > 0, 'todo.js should not be empty');

// Clean slate
try { fs.unlinkSync(todoJson); } catch (e) {}

// Add two items
execSync('node "' + todoJs + '" add "Buy milk"');
execSync('node "' + todoJs + '" add "Walk dog"');

// Read todo.json — verify two items in order
let data = JSON.parse(fs.readFileSync(todoJson, 'utf8'));
assert.strictEqual(data.length, 2);
assert.strictEqual(data[0].task, 'Buy milk');
assert.strictEqual(data[0].done, false);
assert.strictEqual(data[1].task, 'Walk dog');
assert.strictEqual(data[1].done, false);

// List — verify order (Buy milk before Walk dog)
const listOutput = execSync('node "' + todoJs + '" list').toString();
assert.ok(listOutput.includes('Buy milk'));
assert.ok(listOutput.includes('Walk dog'));
assert.ok(
  listOutput.indexOf('Buy milk') < listOutput.indexOf('Walk dog'),
  'Buy milk should appear before Walk dog in list'
);

// Done the first item
const doneOutput = execSync('node "' + todoJs + '" done 1').toString();
assert.ok(doneOutput.includes('Buy milk'));

// Read todo.json again — verify done flag
data = JSON.parse(fs.readFileSync(todoJson, 'utf8'));
assert.strictEqual(data[0].done, true);
assert.strictEqual(data[1].done, false);

// Read both files (explicitly re‑read to satisfy spec)
assert.ok(fs.readFileSync(todoJs, 'utf8').length > 0, 'todo.js re‑read');
assert.ok(fs.readFileSync(todoJson, 'utf8').length > 0, 'todo.json re‑read');

