#!/usr/bin/env node
const fs = require('fs');
const path = require('path');

const DATA_FILE = path.join(__dirname, 'todo.json');

function readTodos() {
  try {
    return JSON.parse(fs.readFileSync(DATA_FILE, 'utf8'));
  } catch {
    return [];
  }
}

function writeTodos(todos) {
  fs.writeFileSync(DATA_FILE, JSON.stringify(todos, null, 2));
}

const [,, command, ...args] = process.argv;

switch (command) {
  case 'add': {
    const task = args.join(' ');
    if (!task) {
      console.error('Usage: todo add <task>');
      process.exit(1);
    }
    const todos = readTodos();
    todos.push({ id: todos.length + 1, task, done: false });
    writeTodos(todos);
    console.log('Added: ' + task);
    break;
  }
  case 'list': {
    const todos = readTodos();
    if (todos.length === 0) {
      console.log('No todos yet.');
    } else {
      todos.forEach(function(t, i) {
        console.log((i + 1) + '. [' + (t.done ? '✓' : ' ') + '] ' + t.task);
      });
    }
    break;
  }
  case 'done': {
    const index = parseInt(args[0], 10);
    if (isNaN(index) || index < 1) {
      console.error('Usage: todo done <index>');
      process.exit(1);
    }
    const todos = readTodos();
    if (index > todos.length) {
      console.error('Invalid index');
      process.exit(1);
    }
    todos[index - 1].done = true;
    writeTodos(todos);
    console.log('Marked as done: ' + todos[index - 1].task);
    break;
  }
  default:
    console.error('Usage: todo <add|list|done> [args]');
    process.exit(1);
}

